#!/usr/bin/env python3
import csv, datetime, html, json, pathlib, re, urllib.request, xml.etree.ElementTree as ET
from urllib.parse import quote
ROOT = pathlib.Path(__file__).resolve().parents[1]
SITE = ROOT / 'sitecheck'
SITE.mkdir(exist_ok=True)
XML_URL = 'http://www.marcusbeda.com.br/feed/vivareal/yncz3b2guhkliqe9rx684t5fm78037_www.marcusbeda.com.br.xml'
req = urllib.request.Request(XML_URL, headers={'User-Agent':'Mozilla/5.0 EMCAZA dashboard updater','Accept':'application/xml,text/xml,*/*'})
raw = urllib.request.urlopen(req, timeout=60).read()
(SITE / 'feed_vivareal_marcusbeda.xml').write_bytes(raw)
root = ET.fromstring(raw)
ns = {'vr':'http://www.vivareal.com/schemas/1.0/VRSync'}
def txt(el,path):
    if el is None: return ''
    x=el.find(path,ns)
    return (x.text or '').strip() if x is not None and x.text else ''
def money(n):
    try: return f"R$ {int(float(n)):,.0f}".replace(',', '.')
    except Exception: return ''
def tipo(pt):
    m={'Residential / Apartment':'Apartamento','Residential / Home':'Casa','Residential / Condo':'Casa em Condomínio','Residential / Sobrado':'Sobrado','Residential / Land Lot':'Lote'}
    return m.get(pt, (pt or '').replace('Residential / ',''))
def clean_desc(s):
    s=html.unescape(s or '')
    s=re.sub(r'<br\s*/?>',' ',s,flags=re.I)
    s=re.sub(r'<[^>]+>',' ',s)
    return re.sub(r'\s+',' ',s).strip()
imoveis=[]
for l in root.findall('.//vr:Listing',ns):
    lid=txt(l,'vr:ListingID'); url=txt(l,'vr:DetailViewUrl')
    details=l.find('vr:Details',ns); loc=l.find('vr:Location',ns); media=l.find('vr:Media',ns)
    imgs=[]
    if media is not None:
        for item in media.findall('.//vr:Item',ns):
            imgs.append((item.text or item.attrib.get('medium') or '').strip())
    imgs=[x for x in imgs if x]
    price=txt(details,'vr:ListPrice')
    ref=lid.rsplit('-',1)[0] if '-' in lid else lid
    im={'id': re.search(r'/imovel/(\d+)/',url).group(1) if re.search(r'/imovel/(\d+)/',url) else lid,'listing_id':lid,'titulo':txt(l,'vr:Title'),'referencia':ref,'tipo':tipo(txt(details,'vr:PropertyType')),'finalidade':'venda' if txt(l,'vr:TransactionType')=='For Sale' else txt(l,'vr:TransactionType'),'cidade':txt(loc,'vr:City'),'bairro':txt(loc,'vr:Neighborhood'),'endereco':txt(loc,'vr:Address'),'numero':txt(loc,'vr:StreetNumber'),'complemento':txt(loc,'vr:Complement'),'cep':txt(loc,'vr:PostalCode'),'valor':money(price),'valor_num':int(float(price)) if price else None,'dormitorios':txt(details,'vr:Bedrooms'),'banheiros':txt(details,'vr:Bathrooms'),'vagas':txt(details,'vr:Garage'),'suites':txt(details,'vr:Suites'),'area_privativa':(txt(details,'vr:LivingArea')+' m²').strip() if txt(details,'vr:LivingArea') else '','area_total':(txt(details,'vr:LotArea')+' m²').strip() if txt(details,'vr:LotArea') else '','area_terreno':(txt(details,'vr:LotArea')+' m²').strip() if txt(details,'vr:LotArea') else '','descricao':clean_desc(txt(details,'vr:Description')),'imagens':imgs,'imagem_principal':imgs[0] if imgs else '','link':url,'whatsapp':'https://wa.me/5562981162705?text='+quote(f'Tenho interesse no imóvel {ref}: {url}')}
    imoveis.append(im)
base={'meta':{'fonte_oficial':'xml_vivareal','url':XML_URL,'gerado_em_utc':datetime.datetime.now(datetime.UTC).replace(microsecond=0).isoformat(),'total':len(imoveis),'regra_disponibilidade':'Se está no XML/feed oficial do site, está disponível para venda.'},'imoveis':imoveis}
(SITE/'imoveis_marcusbeda.json').write_text(json.dumps(base,ensure_ascii=False,indent=2),encoding='utf-8')
cols=['id','listing_id','referencia','tipo','cidade','bairro','endereco','numero','complemento','cep','valor','valor_num','dormitorios','suites','banheiros','vagas','area_privativa','area_total','link','imagem_principal','descricao']
with open(SITE/'imoveis_marcusbeda.csv','w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=cols); w.writeheader(); [w.writerow({c:x.get(c,'') for c in cols}) for x in imoveis]
def esc(x): return html.escape(str(x or ''))
tipos=sorted({x.get('tipo','') for x in imoveis if x.get('tipo')}); bairros=sorted({x.get('bairro','') for x in imoveis if x.get('bairro')}); cidades=sorted({x.get('cidade','') for x in imoveis if x.get('cidade')})
cards=[]
for im in imoveis:
    searchable=' '.join(str(im.get(k,'')) for k in ['id','listing_id','referencia','tipo','bairro','cidade','endereco','cep','valor','descricao']).lower()
    badge='⭐ Oportunidade' if (im.get('valor_num') or 0)<=500000 else 'Alto padrão' if (im.get('valor_num') or 0)>=1200000 else ''
    cards.append(f'''<article class="card" data-search="{esc(searchable)}" data-tipo="{esc(im.get('tipo'))}" data-bairro="{esc(im.get('bairro'))}" data-cidade="{esc(im.get('cidade'))}" data-valor="{im.get('valor_num') or 0}"><img src="{esc(im.get('imagem_principal'))}" alt="{esc(im.get('referencia'))}" loading="lazy" onerror="this.style.display='none'"><div class="body">{f'<div class="badge">{esc(badge)}</div>' if badge else ''}<div class="ref">{esc(im.get('referencia') or im.get('listing_id'))}</div><h2>{esc(im.get('tipo'))} em {esc(im.get('bairro'))}</h2><div class="price">{esc(im.get('valor'))}</div><div class="addr">{esc(im.get('endereco'))}{', '+esc(im.get('numero')) if im.get('numero') else ''} · CEP {esc(im.get('cep'))}</div><div class="meta"><span>{esc(im.get('cidade'))}</span><span>{esc(im.get('dormitorios') or '-')} qtos</span><span>{esc(im.get('suites') or '-')} suítes</span><span>{esc(im.get('banheiros') or '-')} banh.</span><span>{esc(im.get('vagas') or '-')} vagas</span><span>{esc(im.get('area_privativa') or im.get('area_total') or '')}</span></div><p>{esc((im.get('descricao') or '')[:220])}</p><div class="actions"><button class="copy" type="button">Copiar resposta pronta</button><a href="{esc(im.get('link'))}" target="_blank" rel="noopener">Ver imóvel</a><a class="zap" href="{esc(im.get('whatsapp'))}" target="_blank" rel="noopener">WhatsApp</a></div></div></article>''')
updated=base['meta']['gerado_em_utc']
css="""*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;background:#070d14;color:#f1f5f9}header{position:sticky;top:0;z-index:5;background:linear-gradient(135deg,#080e15,#111827 55%,#0e1420);color:#f8fafc;padding:14px 16px 13px;box-shadow:0 10px 28px #0008;border-bottom:1px solid #2a3342}.brand{display:flex;align-items:center;gap:12px}.brand-logo{width:56px;height:56px;border-radius:14px;object-fit:cover;background:#111827;border:1px solid #2a3342;box-shadow:0 8px 18px #0008}.brand-text{min-width:0}h1{font-size:20px;margin:0;letter-spacing:-.02em}.sub{font-size:12px;color:#8b93a3;margin-top:4px;line-height:1.35}.filters{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:12px 16px;background:#0b111b;position:sticky;top:82px;z-index:4;box-shadow:0 8px 20px #0006;border-bottom:1px solid #2a3342}input,select{width:100%;border:1px solid #2a3342;border-radius:12px;padding:11px;background:#0e1420;color:#f1f5f9;font-size:15px;outline:none}input::placeholder{color:#8b93a3}select{color:#e5e7eb}input:focus,select:focus{border-color:#3b82f6;box-shadow:0 0 0 3px #3b82f633}#q{grid-column:1/-1}.quick{display:flex;gap:8px;overflow:auto;padding:10px 16px;background:#0b111b;border-top:1px solid #182233;border-bottom:1px solid #2a3342;position:sticky;top:187px;z-index:3}.quick button{white-space:nowrap;border:1px solid #2a3342;background:#111827;color:#e5e7eb;font-weight:850;border-radius:999px;padding:9px 12px}.quick button:hover{background:#1f2937}main{padding:14px 12px 80px;display:grid;gap:14px;max-width:840px;margin:0 auto}.count{font-weight:850;padding:0 4px;color:#e5e7eb}.card{background:#0e1420;border-radius:18px;overflow:hidden;box-shadow:0 12px 34px #0007;border:1px solid #2a3342}.card img{width:100%;height:215px;object-fit:cover;background:#111827;border-bottom:1px solid #2a3342}.body{padding:14px}.badge{display:inline-block;background:#1f2937;color:#facc15;border:1px solid #854d0e;font-size:11px;font-weight:900;padding:4px 8px;border-radius:999px;margin-bottom:7px}.ref{font-size:12px;color:#8b93a3;font-weight:850}h2{font-size:17px;margin:4px 0 8px;color:#f8fafc}.price{font-size:23px;font-weight:950;color:#4ade80;margin-bottom:7px}.addr{font-size:12px;color:#8b93a3;margin-bottom:8px}.meta{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}.meta span{font-size:12px;background:#111827;color:#c7d2fe;border:1px solid #2a3342;padding:5px 8px;border-radius:999px}p{font-size:14px;line-height:1.38;color:#cbd5e1}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}a,.copy{text-align:center;text-decoration:none;background:#111827;color:#f8fafc;padding:11px;border-radius:12px;font-weight:850;border:1px solid #2a3342;font-size:14px}.actions a:first-of-type{background:#1f2937}.copy{background:#3b82f6;border-color:#60a5fa;grid-column:1/-1;color:white}a.zap{background:#22c55e;border-color:#4ade80;color:#052e16}.empty{display:none;text-align:center;padding:30px;color:#8b93a3}footer{text-align:center;color:#8b93a3;font-size:11px;padding:6px 12px 30px}.footer-logo{display:block;width:132px;max-width:42vw;margin:0 auto 10px;border-radius:12px;border:1px solid #2a3342;background:#0e1420}@media(min-width:760px){main{grid-template-columns:1fr 1fr}.count{grid-column:1/-1}}"""
js="""const cards=[...document.querySelectorAll('.card')],q=document.querySelector('#q'),tipo=document.querySelector('#tipo'),bairro=document.querySelector('#bairro'),cidade=document.querySelector('#cidade'),valor=document.querySelector('#valor'),count=document.querySelector('#count'),empty=document.querySelector('#empty');function moneyNum(s){return Number((s||'').replace(/\D/g,''))||0}function respostaPronta(c){const ref=c.querySelector('.ref')?.textContent.trim()||'imóvel',h=c.querySelector('h2')?.textContent.trim()||'',price=c.querySelector('.price')?.textContent.trim()||'',meta=[...c.querySelectorAll('.meta span')].map(x=>x.textContent.trim()).join(' · '),link=c.querySelector('.actions a')?.href||'';return `Tenho uma opção que encaixa no que você procura:\n\n${h}\n${price}\n${meta}\nCódigo: ${ref}\n\nFotos e detalhes:\n${link}\n\nSe fizer sentido, me fala que eu te passo as condições e vejo visita/simulação.`}function filter(){let qq=q.value.toLowerCase(),tt=tipo.value,bb=bairro.value,cc=cidade.value,vv=moneyNum(valor.value),n=0;cards.forEach(c=>{let ok=(!qq||c.dataset.search.includes(qq))&&(!tt||c.dataset.tipo===tt)&&(!bb||c.dataset.bairro===bb)&&(!cc||c.dataset.cidade===cc)&&(!vv||Number(c.dataset.valor)<=vv);c.style.display=ok?'block':'none';if(ok)n++});count.textContent=n+' imóveis encontrados';empty.style.display=n?'none':'block'}document.addEventListener('click',async e=>{if(e.target.classList.contains('copy')){const txt=respostaPronta(e.target.closest('.card'));try{await navigator.clipboard.writeText(txt);e.target.textContent='Resposta copiada';setTimeout(()=>e.target.textContent='Copiar resposta pronta',1400)}catch(_){alert(txt)}}if(e.target.dataset.max){valor.value=e.target.dataset.max;filter()}if(e.target.dataset.term){q.value=e.target.dataset.term;filter()}if(e.target.dataset.clear){q.value='';tipo.value='';bairro.value='';cidade.value='';valor.value='';filter()}});[q,tipo,bairro,cidade,valor].forEach(e=>e.addEventListener('input',filter));filter();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});"""
html_doc=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#080e15"><title>Dashboard Imóveis Marcus Béda</title><link rel="manifest" href="manifest.webmanifest"><style>{css}</style></head><body><header><div class="brand"><img class="brand-logo" src="assets/logo-emcaza.jpg" alt="EMCAZA Imóveis"><div class="brand-text"><h1>Imóveis disponíveis</h1><div class="sub">{len(imoveis)} imóveis. Fonte oficial: XML VivaReal do site. Atualizado: {esc(updated)}</div></div></div></header><section class="filters"><input id="q" placeholder="Buscar código, bairro, tipo, CEP ou descrição"><select id="tipo"><option value="">Tipo</option>{''.join(f'<option>{esc(t)}</option>' for t in tipos)}</select><select id="bairro"><option value="">Bairro</option>{''.join(f'<option>{esc(b)}</option>' for b in bairros)}</select><select id="cidade"><option value="">Cidade</option>{''.join(f'<option>{esc(c)}</option>' for c in cidades)}</select><input id="valor" inputmode="numeric" placeholder="Valor máximo"></section><section class="quick"><button data-max="350000">Até 350k</button><button data-max="500000">Até 500k</button><button data-max="750000">Até 750k</button><button data-term="jardim novo mundo">Novo Mundo</button><button data-term="recanto das minas gerais">Recanto</button><button data-term="condomínio">Condomínio</button><button data-clear="1">Limpar</button></section><main><div class="count" id="count"></div>{''.join(cards)}<div class="empty" id="empty">Nenhum imóvel encontrado.</div></main><footer><img class="footer-logo" src="assets/logo-marcus-beda.jpg" alt="Marcus Béda Corretor de Imóveis">Fonte: {esc(XML_URL)}</footer><script>{js}</script></body></html>'''
(ROOT/'index.html').write_text(html_doc,encoding='utf-8')
(ROOT/'manifest.webmanifest').write_text(json.dumps({'name':'Dashboard Imóveis Marcus Béda','short_name':'Imóveis','start_url':'./','display':'standalone','background_color':'#070d14','theme_color':'#080e15','icons':[{'src':'assets/logo-emcaza.jpg','sizes':'512x512','type':'image/jpeg','purpose':'any'}]},ensure_ascii=False,indent=2),encoding='utf-8')
(ROOT/'sw.js').write_text("self.addEventListener('install',e=>self.skipWaiting());self.addEventListener('fetch',e=>{});",encoding='utf-8')
(ROOT/'vercel.json').write_text('{\n  "cleanUrls": true,\n  "trailingSlash": false,\n  "headers": [{"source":"/(.*)","headers":[{"key":"Cache-Control","value":"public, max-age=0, must-revalidate"}]}]\n}\n',encoding='utf-8')
print('gerado', len(imoveis), 'imóveis')
